import sys
import math

def find_time_to_hit_wall(n, omega, v0, theta_deg, w):
    theta_rad = math.radians(theta_deg)
    g = 9.81

    # Initial conditions
    vx = v0 * math.cos(theta_rad)
    vy = v0 * math.sin(theta_rad)

    t_min = float('inf')
    i_min = -1

    for i in range(n):
        x_i, y_i = map(float, sys.stdin.readline().split())

        # Parabolic motion equations
        def parabola(t):
            return x_i + vx * t + 0.5 * omega * t**2

        def height(t):
            return y_i + vy * t - 0.5 * g * t**2

        # Find the roots of the equation parabola(t) = w
        discriminant = (w - x_i)**2 - 4 * 0.5 * omega * (y_i - height(w))
        if discriminant >= 0:
            t1 = ((w - x_i) + math.sqrt(discriminant)) / (2 * 0.5 * omega)
            t2 = ((w - x_i) - math.sqrt(discriminant)) / (2 * 0.5 * omega)

            # Check valid times
            if t1 > 0:
                if height(t1) <= 0:
                    if t1 < t_min:
                        t_min = t1
                        i_min = i + 1
            if t2 > 0:
                if height(t2) <= 0:
                    if t2 < t_min:
                        t_min = t2
                        i_min = i + 1

    return i_min, t_min

if __name__ == "__main__":
    input_data = sys.stdin.read()
    input_lines = input_data.splitlines()

    n, omega, v0, theta_deg, w = map(float, input_lines[0].split())

    result = find_time_to_hit_wall(int(n), omega, v0, theta_deg, w)

    print(result[0], f"{result[1]:.6f}")
